import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from 'react-query';
import { Toaster } from 'react-hot-toast';
import './App.css';

// Simple components for now
const SimpleDashboard = () => (
  <div style={{ padding: '20px', textAlign: 'center' }}>
    <h1>🏠 AI FileMat Dashboard</h1>
    <p>Welcome to the modern file processing tool!</p>
    <div style={{ marginTop: '20px' }}>
      <a href="/processor" style={{ margin: '0 10px' }}>📁 File Processor</a>
      <a href="/ai-chat" style={{ margin: '0 10px' }}>🤖 AI Chat</a>
      <a href="/settings" style={{ margin: '0 10px' }}>⚙️ Settings</a>
    </div>
  </div>
);

const SimpleFileProcessor = () => (
  <div style={{ padding: '20px', textAlign: 'center' }}>
    <h1>📁 File Processor</h1>
    <p>Upload and process your files here!</p>
    <a href="/" style={{ margin: '10px' }}>← Back to Dashboard</a>
  </div>
);

const SimpleAIChat = () => (
  <div style={{ padding: '20px', textAlign: 'center' }}>
    <h1>🤖 AI Chat</h1>
    <p>Chat with AI assistant for file processing!</p>
    <a href="/" style={{ margin: '10px' }}>← Back to Dashboard</a>
  </div>
);

const SimpleSettings = () => (
  <div style={{ padding: '20px', textAlign: 'center' }}>
    <h1>⚙️ Settings</h1>
    <p>Configure your preferences here!</p>
    <a href="/" style={{ margin: '10px' }}>← Back to Dashboard</a>
  </div>
);

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      refetchOnWindowFocus: false,
    },
  },
});

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <Router>
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900 transition-colors duration-200">
          <Routes>
            <Route path="/" element={<SimpleDashboard />} />
            <Route path="/processor" element={<SimpleFileProcessor />} />
            <Route path="/ai-chat" element={<SimpleAIChat />} />
            <Route path="/settings" element={<SimpleSettings />} />
          </Routes>
          <Toaster
            position="top-right"
            toastOptions={{
              duration: 4000,
              style: {
                background: 'white',
                color: 'black',
                border: '1px solid #ccc',
                borderRadius: '0.75rem',
                fontSize: '0.875rem',
              },
            }}
          />
        </div>
      </Router>
    </QueryClientProvider>
  );
}

export default App;
